script:
frappe.ui.form.on("Advisory And Recommendations", {
    refresh(frm) {
        // Remove any previously added instance of this button.
        frm.remove_custom_button(__("PRINT REPORT"));

        // Only allow printing from saved records with a linked client.
        if (frm.is_new() || !frm.doc.identifier) {
            return;
        }

        const client_name = frm.doc.identifier;

        // Check the logged-in user's permission on the server.
        frappe.call({
            method: "financial_assessment.utils.role_management.can_print_assessment_report",
            args: {
                client_name: client_name
            },
            callback: function (r) {
                // Fail closed: only an explicit true grants access.
                if (r.message !== true) {
                    return;
                }

                // Ensure the same record is still open.
                if (
                    !frm.wrapper.isConnected ||
                    frm.doc.identifier !== client_name
                ) {
                    return;
                }

                frm.add_custom_button(
                    __("PRINT REPORT"),
                    function () {
                        // Recheck permission immediately before printing.
                        frappe.call({
                            method: "financial_assessment.utils.role_management.can_print_assessment_report",
                            args: {
                                client_name: client_name
                            },
                            callback: function (response) {
                                if (response.message !== true) {
                                    frappe.msgprint({
                                        title: __("Access Denied"),
                                        message: __(
                                            "You do not have permission to print this report."
                                        ),
                                        indicator: "red"
                                    });
                                    return;
                                }

                                const url =
                                    "/printview" +
                                    "?doctype=" +
                                    encodeURIComponent("Client Information") +
                                    "&name=" +
                                    encodeURIComponent(client_name) +
                                    "&format=" +
                                    encodeURIComponent("Financial Assessment Report") +
                                    "&no_letterhead=0";

                                window.open(url, "_blank");
                            },
                            error: function () {
                                frappe.msgprint({
                                    title: __("Access Denied"),
                                    message: __(
                                        "Unable to verify print permission. Printing has been blocked."
                                    ),
                                    indicator: "red"
                                });
                            }
                        });
                    }
                ).addClass("btn-primary");
            },
            error: function () {
                // Do not display the button if permission verification fails.
                console.warn(
                    "Unable to verify assessment print permission."
                );
            }
        });
    }
});
